actions.script:
const gate = ec.service.sync().name('mantle.work.ProjectServices.get#MilestoneApprovalAccess').parameters({workEffortId: workEffortId || '', need: 'none'}).call() || {}
const money = ec.service.sync().name('ironstone.projects.BillingServices.check#Money').parameters({need: 'none'}).call()?.managesMoney
const content = gate.canView && (money || gate.isApprover) ? ec.entity.find('mantle.work.effort.WorkEffortContent').condition('workEffortContentId', workEffortContentId || '')
        .condition('workEffortId', workEffortId || '').disableAuthz().one() : null
ec.message.clearErrors()
if (content?.contentLocation) ec.web.sendResourceResponse(content.contentLocation, true)
else ec.web.sendJsonResponse({errors: ec.l10n.localize('The file is not available')})

const out = ec.service.sync().name('ironstone.projects.PlanningServices.search#PlanItemCandidates').parameters({workEffortId: workEffortId || '', term: term || ''}).call() || {}
ec.message.clearErrors()
ec.web.sendJsonResponse(out.optionList || [])

const out = ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemDetail').parameters({workEffortId: workEffortId || '', kind: 'milestone'}).call() || {}
ec.message.clearErrors()
recordFound = !!out.detail
if (!recordFound) return
const L = (text) => ec.l10n.localize(text)
const enc = (text) => String(text == null ? '' : text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\u0022/g, '&quot;').replace(/\u0027/g, '&#39;')
milestone = out.detail
canUpdate = !!milestone.canUpdate
const states = [['all', 'All', 'sym_o_select_all', milestone.rowList.length], ['notStarted', 'Not started', 'sym_o_radio_button_unchecked', milestone.rowList.filter((row) => row.state === 'notStarted').length],
    ['inProgress', 'In progress', 'sym_o_pending', milestone.rowList.filter((row) => row.state === 'inProgress').length],
    ['done', 'Done', 'sym_o_task_alt', milestone.rowList.filter((row) => row.state === 'done').length]]
if (!states.some((entry) => entry[0] === state)) state = 'all'
stateChips = states.map(([key, label, icon, count]) => ({label: L(label) + ' · ' + count, icon: icon, on: key === state, params: {workEffortId: workEffortId, state: key}}))
itemRows = state === 'all' ? milestone.rowList : milestone.rowList.filter((row) => row.state === state)
itemRowsCount = itemRows.length
projectUrl = '/qapps/Projects/Projects/ProjectDetail/Roadmap?workEffortId=' + encodeURIComponent(milestone.rootWorkEffortId)
const dates = [milestone.startText ? L('Start') + ' ' + milestone.startText : '', milestone.dueText ? L('Due') + ' ' + milestone.dueText : '',
    milestone.reachedText ? L('Reached') + ' ' + milestone.reachedText : ''].filter((part) => part)
factsHtml = '<div class="row items-center q-gutter-x-md text-body2">'
    + '<m-link href="' + enc(projectUrl) + '"><q-chip dense square clickable icon="sym_o_folder" class="q-ma-none m-tonal text-primary">'
    + enc(milestone.projectName + ' (' + milestone.rootWorkEffortId + ')') + '</q-chip></m-link>'
    + (dates.length ? '<span class="' + (milestone.overdue ? 'text-warning' : '') + '"><q-icon name="sym_o_date_range" size="xs" class="q-mr-xs m-muted"></q-icon>' + enc(dates.join(' · ')) + '</span>' : '')
    + (milestone.startDay ? '<span class="text-caption m-muted">' + enc(L('A phase on the timeline')) + '</span>' : '') + '</div>'
factsTui = {t: 'text', id: 'MilestoneFacts', text: [milestone.projectName + ' (' + milestone.rootWorkEffortId + ')'].concat(dates).join(' · ')}
// the primary move along the flow, and the others in More
const moveLabels = {WeInProgress: ['WeInPlanning', 'WeApproved'].includes(milestone.statusId) ? 'Begin' : 'Resume', WeComplete: 'Reach', WeClosed: 'Close',
    WeInPlanning: 'Re-open', WeApproved: 'Approve', WeOnHold: 'Hold', WeCancelled: 'Cancel'}
const primaryBy = {WeInPlanning: 'WeInProgress', WeApproved: 'WeInProgress', WeInProgress: 'WeComplete', WeOnHold: 'WeInProgress', WeComplete: 'WeClosed',
    WeClosed: 'WeInPlanning', WeCancelled: 'WeInPlanning'}
const moves = canUpdate ? milestone.moveIds.filter((id) => moveLabels[id]) : []
const primaryId = primaryBy[milestone.statusId]
primaryMove = primaryId && moves.includes(primaryId) ? {statusId: primaryId, label: L(moveLabels[primaryId])} : null
otherMoves = moves.filter((id) => id !== primaryId).map((id) => ({statusId: id, label: L(moveLabels[id]), danger: id === 'WeCancelled'}))
moveIds = otherMoves.map((move) => move.statusId)
beginLabel = L(moveLabels.WeInProgress)
unfinishedCount = milestone.rowList.filter((row) => row.state === 'notStarted' || row.state === 'inProgress').length
moveOptions = [{key: '', text: L('Out of any milestone')}].concat(milestone.otherOptions)
// the gate, the billing share and the deliverables (impl-projects.md P8b)
extras = ec.service.sync().name('ironstone.projects.PlanningServices.get#MilestoneExtras').parameters({workEffortId: workEffortId}).call()?.extras || {required: false,
    requestRows: [], shareRows: [], deliverables: [], approverOptions: [], lineOptions: []}
ec.message.clearErrors()
// a gated milestone not approved is reached by its approval, not by Reach
gateBlocks = !!extras.required && !extras.approved
if (gateBlocks) {
    if (primaryMove?.statusId === 'WeComplete') primaryMove = null
    otherMoves = otherMoves.filter((move) => move.statusId !== 'WeComplete' && move.statusId !== 'WeClosed')
    moveIds = otherMoves.map((move) => move.statusId)
}
// a client contact (impl-projects.md P10b): decides the gate it is the approver of, opens the estimate only then, accepts no
// deliverable here and sees nothing to change
if (clientUser) {
    extras = Object.assign({}, extras, {canRequest: false, canSetGate: false, canCancel: false, canAccept: false, canEditDeliverables: false,
        canEditShares: false, canInvoice: false, managesMoney: false, canDecide: !!extras.canDecide && !!extras.isApprover})
    if (!extras.isApprover) extras.requestRows = Array.from(extras.requestRows || []).map((row) => Object.assign({}, row, {fileUrl: null}))
}
requestRows = extras.requestRows
shareRows = extras.shareRows
deliverableRows = extras.deliverables
gateValue = {workEffortId: workEffortId, approvalRequired: extras.required ? 'Y' : 'N', approverPartyId: extras.approverPartyId || (extras.approverOptions[0]?.key || '')}
approveNote = extras.isApprover ? '' : ec.resource.expand('You record the approval of ${approver}.', '', {approver: extras.approverName})
deliverableTypes = Array.from(ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', 'DeliverableType').orderBy('sequenceNum').useCache(true).list())
        .map((one) => ({key: one.enumId, text: one.description}))
if (extras.required) factsHtml = factsHtml.replace(/<\/div>$/, '<q-chip dense square icon="sym_o_approval" class="q-ma-none m-tonal text-' + enc(extras.gateColor) + '">'
    + enc(L('Gate') + ': ' + extras.gateText) + '</q-chip></div>')
doneValue = milestone.doneOfTotal
percentValue = milestone.percentDone + '%'
hoursValue = milestone.hoursText || '—'
pointsValue = milestone.pointsText || '—'
